#include <iostream>
#include <ext/pb_ds/assoc_container.hpp>
#include <ext/pb_ds/tree_policy.hpp>

using namespace std;
using namespace __gnu_pbds;

typedef tree<
    pair<long long, int>,
    null_type,
    less<pair<long long, int>>,
    rb_tree_tag,
    tree_order_statistics_node_update
> ordered_set;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    ordered_set ost;
    long long prev_p = 0;

    for (int i = 1; i <= n; ++i) {
        long long x, y;
        cin >> x >> y;

        long long xr = x + prev_p;
        long long yr = y + prev_p;

        long long dist_sq = xr * xr + yr * yr;

        // O número de elementos com distância <= dist_sq é equivalente a
        // contar elementos menores que (dist_sq, infinito).
        long long penalty = ost.order_of_key({dist_sq, i + 1});

        cout << penalty << "\n";

        ost.insert({dist_sq, i});
        prev_p = penalty;
    }

    return 0;
}
